require "rails_helper"

RSpec.describe "Timekeeping handoff load from an unauthenticated caller" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:refused_load_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => refused_load_token
    ) { example.run }
  end

  def refused_load_table_rows
    %w[entries reservations invoice_operations audit_events idempotency_receipts].index_with do |table|
      ApplicationRecord.connection.select_rows("SELECT * FROM #{table} ORDER BY 1, 2")
    end
  end

  # "Every handoff endpoint refuses a caller without service credentials"
  # A 401 sent after the replace ran would still pass a status-only check.
  it "refuses a load from a caller without the service token and leaves the tables unchanged" do
    Timekeeping::Admission.fence!
    get "/internal/v1/handoff/checkpoint", headers: { "Authorization" => "Bearer #{refused_load_token}" }
    expect(response.status).to eq(200)
    empty_checkpoint = response.body

    Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                  note: "Kept", bill_status: "unbilled", source: "manual", source_metadata: {})
    before = refused_load_table_rows
    owner_token = mint_token({ sub: 7, company_id: 1, role: "owner" })

    [nil, "Bearer #{owner_token}", "Bearer #{refused_load_token}x"].each do |authorization|
      headers = { "Content-Type" => "application/json" }
      headers["Authorization"] = authorization if authorization
      put "/internal/v1/handoff/checkpoint", params: empty_checkpoint, headers: headers

      expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])
    end
    expect(refused_load_table_rows).to eq(before)
  end
end

RSpec.describe "Timekeeping handoff entry id sequence" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:sequence_token) { "service-#{SecureRandom.hex(24)}" }
  let(:sequence_auth) { { "Authorization" => "Bearer #{sequence_token}" } }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => sequence_token
    ) { example.run }
  end

  def advance_sequence_for_spec(above)
    post "/internal/v1/handoff/entry_id_sequence", params: { above: }, headers: sequence_auth, as: :json
    [response.status, response.parsed_body]
  end

  # "Advance sequence: set the `entries` id sequence above a given id "only if
  # the new value is higher than its current one"."
  it "keeps the entry id sequence where it is when asked to move it lower or given a non-integer" do
    expect(advance_sequence_for_spec(100)).to eq([200, { "next_id" => 101 }])
    expect(advance_sequence_for_spec(10)).to eq([200, { "next_id" => 101 }])
    expect(advance_sequence_for_spec("3")).to eq([400, { "reason" => "invalid_request" }])
    expect(advance_sequence_for_spec(-1)).to eq([400, { "reason" => "invalid_request" }])

    entry = Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                          note: "After advance", bill_status: "unbilled", source: "manual", source_metadata: {})
    expect(entry.id).to eq(101)
  end
end

RSpec.describe "Timekeeping handoff correction snapshots delivered more than once" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:correction_token) { "service-#{SecureRandom.hex(24)}" }
  let(:correction_auth) { { "Authorization" => "Bearer #{correction_token}" } }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => correction_token
    ) { example.run }
  end

  def correction_snapshot_for_spec(entry, locked:)
    entry.attributes.slice(*(Timekeeping::OutboxFields::ENTRY_FIELDS - ["version"]))
      .merge("locked" => locked).as_json
  end

  def put_corrections_for_spec(snapshots)
    put "/internal/v1/handoff/correction_snapshots",
        params: { generation: 2, version: 1, snapshots: }, headers: correction_auth, as: :json
    [response.status, response.parsed_body]
  end

  def correction_rows_for_spec
    OutboxSnapshot.order(:outbox_position).pluck(:company_id, :id, :generation, :version, :locked)
  end

  # "Writing the same corrections again replaces them, so there is never a
  # second snapshot for one entry and generation."
  it "keeps one correction snapshot per entry when the same corrections arrive twice and refuses one entry named twice in a request" do
    first, second = 2.times.map do
      Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                    note: "Corrected", bill_status: "unbilled", source: "manual", source_metadata: {})
    end
    Timekeeping::Admission.fence!
    corrections = [correction_snapshot_for_spec(first, locked: false), correction_snapshot_for_spec(second, locked: false)]

    expect(put_corrections_for_spec(corrections)).to eq([200, { "written" => 2 }])
    expect(put_corrections_for_spec(corrections)).to eq([200, { "written" => 2 }])
    expect(correction_rows_for_spec).to contain_exactly([1, first.id, 2, 1, false], [1, second.id, 2, 1, false])

    before = correction_rows_for_spec
    duplicate = [correction_snapshot_for_spec(first, locked: false), correction_snapshot_for_spec(first, locked: true)]

    expect(put_corrections_for_spec(duplicate)).to eq([400, { "reason" => "invalid_request" }])
    expect(correction_rows_for_spec).to eq(before)
  end
end

RSpec.describe "Timekeeping handoff admission with a malformed generation" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:admit_token) { "service-#{SecureRandom.hex(24)}" }
  let(:admit_auth) { { "Authorization" => "Bearer #{admit_token}" } }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => admit_token
    ) { example.run }
  end

  # "Admission: fence and admit through `Timekeeping::Admission.fence!` and
  # `Timekeeping::Admission.admit!`, from the admission-fence work this depends
  # on. This endpoint only calls them."
  # A refused admit must never answer success, or the caller would believe
  # writes are admitted while Timekeeping is still fenced.
  it "refuses to admit a generation sent as a string and leaves Timekeeping fenced" do
    post "/internal/v1/handoff/admission/fence", headers: admit_auth, as: :json
    expect(response.status).to eq(200)

    ["3", 0].each do |generation|
      post "/internal/v1/handoff/admission/admit", params: { generation: }, headers: admit_auth, as: :json

      expect([response.status, response.parsed_body]).to eq([400, { "reason" => "invalid_request" }])
      expect(Timekeeping::Admission.current.generation).to be_nil
    end
  end
end
